import { readFile, writeFile, rename } from 'node:fs/promises'
import { randomBytes } from 'node:crypto'

// Persists books as a JSON array. Writes go through a temp file so a
// crash mid-write can't truncate the data file.
export function createStore(filePath) {
  let books = []

  async function load() {
    try {
      books = JSON.parse(await readFile(filePath, 'utf8'))
    } catch (err) {
      if (err.code !== 'ENOENT') throw err
      books = []
    }
  }

  async function save() {
    const tmp = filePath + '.tmp'
    await writeFile(tmp, JSON.stringify(books, null, 2) + '\n')
    await rename(tmp, filePath)
  }

  return {
    load,

    all() {
      return books
    },

    get(id) {
      return books.find((b) => b.id === id)
    },

    async add({ title, author, notes = '' }) {
      const book = {
        id: randomBytes(5).toString('hex'),
        title,
        author,
        notes,
        finished: false,
        addedAt: new Date().toISOString(),
      }
      books.push(book)
      await save()
      return book
    },

    async finish(id) {
      const book = this.get(id)
      if (!book) return undefined
      if (!book.finished) {
        book.finished = true
        book.finishedAt = new Date().toISOString()
        await save()
      }
      return book
    },
  }
}

