import { createServer } from 'node:http'
import { createStore } from './lib/store.mjs'

const PORT = process.env.PORT || 3000
const DATA_FILE = process.env.DATA_FILE || new URL('./books.json', import.meta.url).pathname

const store = createStore(DATA_FILE)
await store.load()

function esc(s) {
  return String(s)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
}

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; color: #222; line-height: 1.5; }
  h1 { font-size: 1.5rem; } h1 a { color: inherit; text-decoration: none; }
  h2 { font-size: 1.1rem; margin-top: 2rem; border-bottom: 1px solid #ddd; padding-bottom: .3rem; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; align-items: baseline; gap: .5rem; padding: .4rem 0; }
  ul.books .author { color: #666; }
  ul.books form { margin-left: auto; }
  form.add { margin-top: 1rem; display: grid; gap: .5rem; }
  input, textarea { font: inherit; padding: .4rem; border: 1px solid #bbb; border-radius: 4px; width: 100%; box-sizing: border-box; }
  textarea { min-height: 5rem; }
  button { font: inherit; padding: .3rem .8rem; border: 1px solid #888; border-radius: 4px; background: #f4f4f4; cursor: pointer; }
  button:hover { background: #e8e8e8; }
  .notes { white-space: pre-wrap; background: #f8f8f8; border-radius: 4px; padding: .8rem; }
  .muted { color: #666; }
</style>
</head>
<body>
<h1><a href="/">📚 My Books</a></h1>
${body}
</body>
</html>`
}

function bookItem(book) {
  const finishBtn = book.finished
    ? ''
    : `<form method="post" action="/book/${book.id}/finish"><button>Mark finished</button></form>`
  return `<li>
    <a href="/book/${book.id}">${esc(book.title)}</a>
    <span class="author">by ${esc(book.author)}</span>
    ${finishBtn}
  </li>`
}

function homePage() {
  const reading = store.all().filter((b) => !b.finished)
  const finished = store.all().filter((b) => b.finished)
  return page('My Books', `
<h2>Currently reading</h2>
${reading.length ? `<ul class="books">${reading.map(bookItem).join('')}</ul>` : '<p class="muted">Nothing on the go right now.</p>'}

<h2>Finished</h2>
${finished.length ? `<ul class="books">${finished.map(bookItem).join('')}</ul>` : '<p class="muted">Nothing finished yet.</p>'}

<h2>Add a book</h2>
<form class="add" method="post" action="/books">
  <input name="title" placeholder="Title" required>
  <input name="author" placeholder="Author" required>
  <textarea name="notes" placeholder="Notes (optional)"></textarea>
  <div><button>Add book</button></div>
</form>`)
}

function bookPage(book) {
  const status = book.finished
    ? `Finished ${esc(book.finishedAt.slice(0, 10))}`
    : `<form method="post" action="/book/${book.id}/finish" style="display:inline"><button>Mark finished</button></form>`
  return page(book.title, `
<h2>${esc(book.title)}</h2>
<p class="author muted">by ${esc(book.author)}</p>
<p>${status}</p>
${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : '<p class="muted">No notes yet.</p>'}
<p><a href="/">← Back to all books</a></p>`)
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = ''
    req.on('data', (chunk) => {
      body += chunk
      if (body.length > 100_000) reject(new Error('body too large'))
    })
    req.on('end', () => resolve(Object.fromEntries(new URLSearchParams(body))))
    req.on('error', reject)
  })
}

function send(res, status, html) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' })
  res.end(html)
}

function redirect(res, location) {
  res.writeHead(303, { location })
  res.end()
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost')
    const bookMatch = url.pathname.match(/^\/book\/([a-f0-9]+)$/)
    const finishMatch = url.pathname.match(/^\/book\/([a-f0-9]+)\/finish$/)

    if (req.method === 'GET' && url.pathname === '/') {
      return send(res, 200, homePage())
    }
    if (req.method === 'GET' && bookMatch) {
      const book = store.get(bookMatch[1])
      if (!book) return send(res, 404, page('Not found', '<p>Book not found. <a href="/">Back</a></p>'))
      return send(res, 200, bookPage(book))
    }
    if (req.method === 'POST' && url.pathname === '/books') {
      const form = await readForm(req)
      const title = (form.title || '').trim()
      const author = (form.author || '').trim()
      if (!title || !author) {
        return send(res, 400, page('Missing fields', '<p>Title and author are required. <a href="/">Back</a></p>'))
      }
      const book = await store.add({ title, author, notes: (form.notes || '').trim() })
      return redirect(res, `/book/${book.id}`)
    }
    if (req.method === 'POST' && finishMatch) {
      const book = await store.finish(finishMatch[1])
      if (!book) return send(res, 404, page('Not found', '<p>Book not found. <a href="/">Back</a></p>'))
      return redirect(res, req.headers.referer?.endsWith(`/book/${book.id}`) ? `/book/${book.id}` : '/')
    }
    send(res, 404, page('Not found', '<p>Page not found. <a href="/">Back</a></p>'))
  } catch (err) {
    console.error(err)
    send(res, 500, page('Error', '<p>Something went wrong. <a href="/">Back</a></p>'))
  }
})

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`)
})

