import { test, expect } from 'vitest'
import { mkdtemp, readFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createStore } from './store.mjs'

async function tmpStore() {
  const dir = await mkdtemp(join(tmpdir(), 'books-'))
  const file = join(dir, 'books.json')
  const store = createStore(file)
  await store.load()
  return { store, file }
}

test('starts empty when file does not exist', async () => {
  const { store } = await tmpStore()
  expect(store.all()).toEqual([])
})

test('add creates a book and persists it', async () => {
  const { store, file } = await tmpStore()
  const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'sandy' })
  expect(book.id).toMatch(/^[a-f0-9]{10}$/)
  expect(book.finished).toBe(false)

  const onDisk = JSON.parse(await readFile(file, 'utf8'))
  expect(onDisk).toHaveLength(1)
  expect(onDisk[0].title).toBe('Dune')
})

test('finish marks a book and survives a reload', async () => {
  const { store, file } = await tmpStore()
  const book = await store.add({ title: 'Dune', author: 'Frank Herbert' })
  const finished = await store.finish(book.id)
  expect(finished.finished).toBe(true)
  expect(finished.finishedAt).toBeDefined()

  const reloaded = createStore(file)
  await reloaded.load()
  expect(reloaded.get(book.id).finished).toBe(true)
})

test('finish returns undefined for unknown id', async () => {
  const { store } = await tmpStore()
  expect(await store.finish('nope')).toBeUndefined()
})

